73	    /** Every claim on the sheet by the person who made it, each person's newest first. */
74	    @Transactional(readOnly = true)
75	    public Map<Long, List<Claim>> bySheet(String sheetId) {
76	        return claims.findBySheetIdOrderByListedDesc(sheetId).stream()
77	                .collect(Collectors.groupingBy(Claim::getPersonId));
78	    }
79	
80	    @Transactional(readOnly = true)
81	    public List<Claim> forPerson(String sheetId, long personId) {
82	        return claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
83	    }
