85	    /** Add a claim; a date left out takes the sheet's entry date while set, else its today. Returns the person it belongs to. */
86	    @Transactional
87	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
88	        return add(sheetId, user, personId, amount, date, note, null);
89	    }
