91	    /**
92	     * Add a claim, a correction naming the number of the claim it corrects; a date left out takes the
93	     * sheet's entry date while set, else its today. Returns the person it belongs to.
94	     */
95	    @Transactional
96	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
97	            String corrects) {
98	        Person person = people.findByIdAndSheetId(personId, sheetId)
99	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
100	        LocalDate on = date != null ? date : sheets.claimDate(sheetId);
101	        periods.requireOpen(sheetId, on);
102	        requireNotRetired(person, on);
103	        LocalDate correctsDate = requireCorrects(sheetId, personId, amount, corrects);
104	        Rollup.Figures before = rollup.figures(sheetId);
105	        Claim claim = new Claim(sheetId, personId, amount, on, note == null ? "" : note, corrects);
106	        claim.setCorrectsDate(correctsDate);
107	        claim.setLateEntry(periods.softClosedOn(sheetId, on).isPresent());
108	        sheets.load(sheetId, user);
109	        claim.setDueBy(on.plusDays(sheets.settings(sheetId).termsFor(person.getTerms(), person.gradeOn(on), on)));
110	        log(sheetId, user, claim, person);
111	        claims.saveAndFlush(claim);
112	        events.publishEvent(new ClaimChanged("CLAIM_ADDED", sheetId, user, person.getName(), amount, on, null, null));
113	        if (claim.isLateEntry()) {
114	            events.publishEvent(new ClaimChanged("LATE_ENTRY", sheetId, user, person.getName(), amount, on, null, null));
115	        }
116	        rollup.changed(sheetId, user, before);
117	        return personId;
118	    }
