120	    /**
121	     * Edit a claim's amount, date and note; only a DRAFT can be edited (an open claim is voided and
122	     * added again instead), and an edit is refused when a closed period contains its date or the new one, or
123	     * when the date it is left with is after its person's retirement date.
124	     * Returns the person it belongs to.
125	     */
126	    @Transactional
127	    public long edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
128	            String corrects) {
129	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
130	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
131	        LocalDate on = date != null ? date : sheets.today(sheetId);
132	        periods.requireOpen(sheetId, claim.getDate(), on);
133	        if (claim.getStatus() != ClaimStatus.DRAFT) {
134	            throw new ResponseStatusException(HttpStatus.CONFLICT,
135	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
136	        }
137	        requireNotLockedByOther(claim, user);
138	        people.findByIdAndSheetId(claim.getPersonId(), sheetId).ifPresent(p -> requireNotRetired(p, on));
139	        LocalDate correctsDate = requireCorrects(sheetId, claim.getPersonId(), amount, corrects);
140	        Rollup.Figures before = rollup.figures(sheetId);
141	        claim.setAmount(amount);
142	        claim.setCorrects(corrects);
143	        claim.setCorrectsDate(correctsDate);
144	        claim.setDate(on);
145	        claim.setNote(note == null ? "" : note);
146	        claim.setLockedBy(null);
147	        claims.flush();
148	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
149	        events.publishEvent(new ClaimChanged("CLAIM_EDITED", sheetId, user, person, claim.getAmount(),
150	                claim.getDate(), claim.getShownNumber(), null));
151	        rollup.changed(sheetId, user, before);
152	        return claim.getPersonId();
153	    }
