155	    /**
156	     * Open a claim's editor, locking the claim for every other user until the editor is saved or cancelled
157	     * or the sheet's today changes. Only a DRAFT dated outside every closed period can be edited, and a claim
158	     * another user's editor holds is refused; a refusal takes no lock. No audit line. Returns the person
159	     * it belongs to.
160	     */
161	    @Transactional
162	    public long lock(String sheetId, String user, long claimId) {
163	        Claim claim = claim(sheetId, claimId);
164	        if (claim.getStatus() != ClaimStatus.DRAFT) {
165	            throw new ResponseStatusException(HttpStatus.CONFLICT,
166	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
167	        }
168	        requireNotLockedByOther(claim, user);
169	        claim.setLockedBy(user);
170	        claims.flush();
171	        return claim.getPersonId();
172	    }
173	
174	    /** Cancel a claim's editor, releasing the user's lock on it; another user's lock stays. Returns the person. */
175	    @Transactional
176	    public long unlock(String sheetId, String user, long claimId) {
177	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
178	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
179	        if (user.equals(claim.getLockedBy())) {
180	            claim.setLockedBy(null);
181	            claims.flush();
182	        }
183	        return claim.getPersonId();
184	    }
