186	    /** A change of the sheet's today releases every editor's lock on its claims. */
187	    @EventListener
188	    @Transactional
189	    public void on(TodayChanged e) {
190	        claims.findBySheetIdAndLockedByIsNotNull(e.sheetId()).forEach(c -> c.setLockedBy(null));
191	        claims.flush();
192	    }
