194	    private static void requireNotLockedByOther(Claim claim, String user) {
195	        if (claim.getLockedBy() != null && !claim.getLockedBy().equals(user)) {
196	            throw new ResponseStatusException(HttpStatus.CONFLICT,
197	                    "The claim is being edited by " + claim.getLockedBy());
198	        }
199	    }
