201	    /**
202	     * Move a claim to a status; a move its status does not allow, opening, settling or voiding by a role the
203	     * sheet's permission matrix does not allow, settling by the user who opened
204	     * the claim, or moving a claim dated inside a closed period, is refused and changes nothing. Settling
205	     * by a clerk a claim whose due is above the clerk limit leaves it PENDING.
206	     * Returns the person it belongs to.
207	     */
208	    @Transactional
209	    public long move(String sheetId, String user, long claimId, ClaimStatus next) {
210	        Claim claim = claim(sheetId, claimId);
211	        if (!claim.getStatus().canBecome(next)) {
212	            throw new ResponseStatusException(HttpStatus.CONFLICT,
213	                    "A " + claim.getStatus() + " claim cannot become " + next);
214	        }
215	        Permission permission = switch (next) {
216	            case OPEN -> Permission.OPEN;
217	            case SETTLED -> Permission.SETTLE;
218	            case VOID -> Permission.VOID;
219	            default -> null;
220	        };
221	        if (permission != null && !access.allows(sheetId, user, permission)) {
222	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
223	                    "Your role may not " + permission.action() + " a claim on this sheet");
224	        }
225	        String reversed = null;
226	        if (next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
227	            requireVoidableSettled(sheetId, user, claim);
228	            reversed = claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString();
229	        }
230	        if (next == ClaimStatus.SETTLED && Dues.deferred(claim, sheets.today(sheetId))) {
231	            throw new ResponseStatusException(HttpStatus.CONFLICT,
232	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be settled before then");
233	        }
234	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
235	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
236	                    "The user who opened a claim cannot settle it");
237	        }
238	        if (next == ClaimStatus.OPEN) {
239	            requireNote(sheetId, claim);
240	        }
241	        Rollup.Figures before = rollup.figures(sheetId);
242	        if (next == ClaimStatus.OPEN) {
243	            giveNumber(sheetId, claim);
244	            claim.setOpenedBy(user);
245	        }
246	        String number = claim.getShownNumber();
247	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
248	        String due = null;
249	        if (next == ClaimStatus.SETTLED) {
250	            BigDecimal fixed = dueNow(sheetId, claim, owner);
251	            requireProof(sheetId, claim, fixed);
252	            if (access.canSettle(sheetId, user, fixed)) {
253	                claim.setSettledDue(fixed);
254	                due = fixed == null ? "n/a" : fixed.toPlainString();
255	            } else {
256	                next = ClaimStatus.PENDING;
257	            }
258	        }
259	        claim.setStatus(next);
260	        log(sheetId, user, claim, owner);
261	        claims.flush();
262	        String person = owner == null ? "" : owner.getName();
263	        String event = switch (next) {
264	            case OPEN -> "CLAIM_OPENED";
265	            case PENDING -> "CLAIM_PENDING";
266	            case SETTLED -> "CLAIM_SETTLED";
267	            case VOID -> "CLAIM_VOIDED";
268	            case DRAFT -> throw new IllegalStateException();
269	        };
270	        events.publishEvent(new ClaimChanged(event, sheetId, user, person, claim.getAmount(), claim.getDate(), number,
271	                due, null, reversed));
272	        if (next == ClaimStatus.SETTLED) {
273	            watches.notifyWatchers(sheetId, user, owner, number);
274	        }
275	        rollup.changed(sheetId, user, before);
276	        return claim.getPersonId();
277	    }
278	
279	    /**
280	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim
281	     * counts in no total, is not overdue, cannot be settled and no statement binds it (see
282	     * {@link Dues#deferred}). A claim not OPEN, a date not after today, or a claim dated inside a closed
283	     * period is refused and nothing changes. Returns the person it belongs to.
284	     */
285	    @Transactional
286	    public long defer(String sheetId, String user, long claimId, LocalDate until) {
287	        Claim claim = claim(sheetId, claimId);
288	        if (claim.getStatus() != ClaimStatus.OPEN) {
289	            throw new ResponseStatusException(HttpStatus.CONFLICT,
290	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can");
291	        }
292	        LocalDate today = sheets.today(sheetId);
293	        if (!until.isAfter(today)) {
294	            throw new ResponseStatusException(HttpStatus.CONFLICT,
295	                    "A claim can only be deferred to a date after the sheet's today (" + today + ")");
296	        }
297	        Rollup.Figures before = rollup.figures(sheetId);
298	        claim.setDeferredUntil(until);
299	        claims.flush();
300	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
301	        events.publishEvent(new ClaimDeferred(sheetId, user, person, claim.getAmount(), claim.getDate(),
302	                claim.getShownNumber(), until));
303	        rollup.changed(sheetId, user, before);
304	        return claim.getPersonId();
305	    }
306	
307	    /**
308	     * A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure a statement
309	     * bound it to stays bound; its period follows the new date. While period numbering is on and the new
310	     * date falls in another period (or none) than the old, the claim takes the next number of its new
311	     * period's sequence, and its old place is never given again. A claim not OPEN or PENDING, one dated
312	     * inside a closed period, a new date inside one or after its person's retirement date, or a re-date by
313	     * anyone but a steward is refused and nothing changes. Returns the person it belongs to.
314	     */
315	    @Transactional
316	    public long redate(String sheetId, String user, long claimId, LocalDate date) {
317	        Claim claim = claim(sheetId, claimId);
318	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
319	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can re-date a claim");
320	        }
321	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
322	            throw new ResponseStatusException(HttpStatus.CONFLICT,
323	                    "A " + claim.getStatus() + " claim cannot be re-dated; only an OPEN or PENDING one can");
324	        }
325	        periods.requireOpen(sheetId, date);
326	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
327	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
328	        requireNotRetired(owner, date);
329	        Rollup.Figures before = rollup.figures(sheetId);
330	        LocalDate old = claim.getDate();
331	        claim.setDate(date);
332	        if (numberingOn(sheetId) && !sequenceOf(sheetId, old).equals(sequenceOf(sheetId, date))) {
333	            if (claim.getPeriodSequence() != null) {
334	                claims.retireNumber(sheetId, claim.getPeriodSequence(), claim.getPeriodSeqNumber());
335	            }
336	            giveNumber(sheetId, claim);
337	        }
338	        claims.flush();
339	        events.publishEvent(new ClaimRedated(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
340	                claim.getShownNumber(), old, date));
341	        rollup.changed(sheetId, user, before);
342	        return claim.getPersonId();
343	    }
344	
345	    /**
346	     * Split an amount (more than 0.00 and less than the claim's amount) off an OPEN claim. The claim keeps
347	     * the rest and is released from any figure a statement bound it to; a new OPEN claim of the same person
348	     * takes the amount split off, with the same date and note, the next number, opened by the user and
349	     * due by its date plus the terms then of its person's grade on its date, naming the claim it was split
350	     * from. A claim not OPEN, a deferred one, one dated inside a closed period, an amount out of range, or a
351	     * split by a role the sheet's permission matrix does not allow to open a claim is refused and nothing
352	     * changes. Returns the person it belongs to.
353	     */
354	    @Transactional
355	    public long split(String sheetId, String user, long claimId, BigDecimal amount) {
356	        Claim claim = claim(sheetId, claimId);
357	        if (claim.getStatus() != ClaimStatus.OPEN) {
358	            throw new ResponseStatusException(HttpStatus.CONFLICT,
359	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can");
360	        }
361	        if (Dues.deferred(claim, sheets.today(sheetId))) {
362	            throw new ResponseStatusException(HttpStatus.CONFLICT,
363	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be split");
364	        }
365	        if (!access.allows(sheetId, user, Permission.OPEN)) {
366	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim on this sheet");
367	        }
368	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
369	            throw new ResponseStatusException(HttpStatus.CONFLICT,
370	                    "The amount split off must be more than 0.00 and less than " + claim.getAmount().toPlainString());
371	        }
372	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
373	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
374	        Rollup.Figures before = rollup.figures(sheetId);
375	        claim.setAmount(claim.getAmount().subtract(amount));
376	        claim.unbind();
377	        Claim part = new Claim(sheetId, owner.getId(), amount, claim.getDate(), claim.getNote(), null);
378	        sheets.load(sheetId, user);
379	        part.setDueBy(claim.getDate().plusDays(
380	                sheets.settings(sheetId).termsFor(owner.getTerms(), owner.gradeOn(claim.getDate()), claim.getDate())));
381	        part.setSplitFrom(claim.getShownNumber());
382	        giveNumber(sheetId, part);
383	        part.setOpenedBy(user);
384	        part.setStatus(ClaimStatus.OPEN);
385	        log(sheetId, user, part, owner);
386	        claims.saveAndFlush(part);
387	        events.publishEvent(new ClaimSplit(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
388	                claim.getShownNumber(), part.getShownNumber()));
389	        events.publishEvent(new ClaimChanged("CLAIM_OPENED", sheetId, user, owner.getName(), part.getAmount(),
390	                part.getDate(), part.getShownNumber(), null));
391	        rollup.changed(sheetId, user, before);
392	        return owner.getId();
393	    }
