395	    /**
396	     * Add a proof to a claim, raising its proofs count by one. A SETTLED or VOID claim, or a claim dated
397	     * inside a closed period, is refused and nothing changes. Returns the person it belongs to.
398	     */
399	    @Transactional
400	    public long addProof(String sheetId, String user, long claimId) {
401	        Claim claim = claim(sheetId, claimId);
402	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
403	            throw new ResponseStatusException(HttpStatus.CONFLICT,
404	                    "A " + claim.getStatus() + " claim cannot take a proof");
405	        }
406	        claim.addProof();
407	        claims.flush();
408	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
409	        events.publishEvent(new ClaimProofAdded(sheetId, user, person, claim.getAmount(), claim.getDate(),
410	                claim.getShownNumber(), claim.getProofs()));
411	        return claim.getPersonId();
412	    }
