414	    /**
415	     * Refuse opening a claim with an empty note whose due (null: n/a) is above the sheet's note threshold in
416	     * force on the claim's date.
417	     */
418	    private void requireNote(String sheetId, Claim claim) {
419	        if (claim.getNote() != null && !claim.getNote().isBlank()) {
420	            return;
421	        }
422	        BigDecimal threshold = sheets.settings(sheetId).noteThreshold(claim.getDate());
423	        if (threshold == null) {
424	            return;
425	        }
426	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
427	        BigDecimal due = dueNow(sheetId, claim, owner);
428	        if (due != null && due.compareTo(threshold) > 0) {
429	            throw new ResponseStatusException(HttpStatus.CONFLICT,
430	                    "A claim with a due above " + threshold.toPlainString() + " needs a note to be opened");
431	        }
432	    }
433	
434	    /**
435	     * Refuse settling or approving a claim with no proof whose due (null: n/a) is above the sheet's proof
436	     * threshold in force on the claim's date.
437	     */
438	    private void requireProof(String sheetId, Claim claim, BigDecimal due) {
439	        if (due == null || claim.getProofs() > 0) {
440	            return;
441	        }
442	        BigDecimal threshold = sheets.settings(sheetId).proofThreshold(claim.getDate());
443	        if (threshold != null && due.compareTo(threshold) > 0) {
444	            throw new ResponseStatusException(HttpStatus.CONFLICT,
445	                    "A claim with a due above " + threshold.toPlainString() + " needs a proof to be settled");
446	        }
447	    }
