449	    /**
450	     * Approve a PENDING claim, settling it with its due fixed now (its live figure, late charge frozen in).
451	     * Only a steward approves, never the user who opened the claim; a claim not PENDING or dated inside a
452	     * closed period is refused and nothing changes. Returns the person it belongs to.
453	     */
454	    @Transactional
455	    public long approve(String sheetId, String user, long claimId) {
456	        Claim claim = pending(sheetId, user, claimId, "approve", "approved");
457	        if (user.equals(claim.getOpenedBy())) {
458	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
459	        }
460	        Rollup.Figures before = rollup.figures(sheetId);
461	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
462	        BigDecimal fixed = dueNow(sheetId, claim, owner);
463	        requireProof(sheetId, claim, fixed);
464	        claim.setSettledDue(fixed);
465	        claim.setStatus(ClaimStatus.SETTLED);
466	        log(sheetId, user, claim, owner);
467	        claims.flush();
468	        events.publishEvent(new ClaimChanged("CLAIM_APPROVED", sheetId, user, owner == null ? "" : owner.getName(),
469	                claim.getAmount(), claim.getDate(), claim.getShownNumber(), fixed == null ? "n/a" : fixed.toPlainString()));
470	        watches.notifyWatchers(sheetId, user, owner, claim.getShownNumber());
471	        rollup.changed(sheetId, user, before);
472	        return claim.getPersonId();
473	    }
474	
475	    /**
476	     * Re-settle a SETTLED claim, fixing its due again at the figure it would have today as an OPEN claim bound
477	     * by no statement (today's rates, grades, floor and late charge), and logging it SETTLED again. Only a
478	     * steward re-settles; a claim not SETTLED or dated inside a closed period is refused and nothing changes.
479	     * Returns the person it belongs to.
480	     */
481	    @Transactional
482	    public long resettle(String sheetId, String user, long claimId) {
483	        Claim claim = claim(sheetId, claimId);
484	        if (claim.getStatus() != ClaimStatus.SETTLED) {
485	            throw new ResponseStatusException(HttpStatus.CONFLICT,
486	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can");
487	        }
488	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
489	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can re-settle a claim");
490	        }
491	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
492	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
493	        Rollup.Figures before = rollup.figures(sheetId);
494	        BigDecimal old = claim.getSettledDue();
495	        BigDecimal fixed = Dues.asOpen(claim, owner::gradeOn, rates.table(sheetId));
496	        claim.setSettledDue(fixed);
497	        claim.logStatus(user, sheets.today(sheetId), fixed);
498	        claims.flush();
499	        events.publishEvent(new ClaimResettled(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
500	                claim.getShownNumber(), old, fixed));
501	        watches.notifyWatchers(sheetId, user, owner, claim.getShownNumber());
502	        rollup.changed(sheetId, user, before);
503	        return claim.getPersonId();
504	    }
505	
506	    /**
507	     * Reject a PENDING claim with a reason, putting it back to OPEN (bound again by the last statement if
508	     * that statement counted it). Only a steward rejects; a claim not PENDING or dated inside a closed
509	     * period is refused and nothing changes. Returns the person it belongs to.
510	     */
511	    @Transactional
512	    public long reject(String sheetId, String user, long claimId, String reason) {
513	        Claim claim = pending(sheetId, user, claimId, "reject", "rejected");
514	        Rollup.Figures before = rollup.figures(sheetId);
515	        claim.setStatus(ClaimStatus.OPEN);
516	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
517	        log(sheetId, user, claim, owner);
518	        claims.flush();
519	        String person = owner == null ? "" : owner.getName();
520	        events.publishEvent(new ClaimChanged("CLAIM_REJECTED", sheetId, user, person, claim.getAmount(),
521	                claim.getDate(), claim.getShownNumber(), null, reason));
522	        rollup.changed(sheetId, user, before);
523	        return claim.getPersonId();
524	    }
525	
526	    /**
527	     * A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. The claim keeps its
528	     * number and date, is released from any figure a statement bound it to (live again until its new
529	     * person's next statement), and lists as its new person's newest claim. A settled or voided claim, a
530	     * correction, a claim dated inside a closed period or after the new person's retirement date, or a move
531	     * by a role the sheet's permission matrix does not allow (a steward, unless set) is refused and nothing changes. Returns the people it moved from and to.
532	     */
533	    @Transactional
534	    public long[] reassign(String sheetId, String user, long claimId, long toPersonId) {
535	        Claim claim = claim(sheetId, claimId);
536	        if (!access.allows(sheetId, user, Permission.REASSIGN)) {
537	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Your role may not reassign a claim on this sheet");
538	        }
539	        if (claim.getStatus() != ClaimStatus.DRAFT && claim.getStatus() != ClaimStatus.OPEN
540	                && claim.getStatus() != ClaimStatus.PENDING) {
541	            throw new ResponseStatusException(HttpStatus.CONFLICT,
542	                    "A " + claim.getStatus() + " claim cannot be reassigned");
543	        }
544	        if (claim.isCorrection()) {
545	            throw new ResponseStatusException(HttpStatus.CONFLICT,
546	                    "A correction belongs with the claim it corrects and cannot be reassigned");
547	        }
548	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
549	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
550	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
551	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "Choose a person on the sheet"));
552	        if (from.getId().equals(to.getId())) {
553	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s");
554	        }
555	        requireNotRetired(to, claim.getDate());
556	        Rollup.Figures before = rollup.figures(sheetId);
557	        claim.setPersonId(to.getId());
558	        claim.unbind();
559	        claims.flush();
560	        claims.relist(claim.getId());
561	        events.publishEvent(new ClaimReassigned(sheetId, user, to.getName(), claim.getAmount(), claim.getDate(),
562	                claim.getShownNumber(), from.getName(), to.getName()));
563	        rollup.changed(sheetId, user, before);
564	        return new long[] { from.getId(), to.getId() };
565	    }
566	
567	    /** The PENDING claim a steward is to approve or reject; refused for anyone else or any other claim. */
568	    private Claim pending(String sheetId, String user, long claimId, String action, String done) {
569	        Claim claim = claim(sheetId, claimId);
570	        if (claim.getStatus() != ClaimStatus.PENDING) {
571	            throw new ResponseStatusException(HttpStatus.CONFLICT,
572	                    "A " + claim.getStatus() + " claim cannot be " + done + "; only a PENDING one can");
573	        }
574	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
575	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can " + action + " a claim");
576	        }
577	        return claim;
578	    }
579	
580	    /**
581	     * A SETTLED claim may be voided only by a steward, and only while the sheet's today is no more than
582	     * 7 days after the date its status log records it SETTLED.
583	     */
584	    private void requireVoidableSettled(String sheetId, String user, Claim claim) {
585	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
586	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may void a SETTLED claim");
587	        }
588	        LocalDate settledOn = claim.getLog().stream().filter(l -> l.getStatus() == ClaimStatus.SETTLED)
589	                .map(ClaimLogLine::getOn).reduce((a, b) -> b).orElse(null);
590	        LocalDate today = sheets.today(sheetId);
591	        if (settledOn == null || today.isAfter(settledOn.plusDays(7))) {
592	            throw new ResponseStatusException(HttpStatus.CONFLICT,
593	                    "A SETTLED claim can only be voided within 7 days of its settlement"
594	                            + (settledOn == null ? "" : " (" + settledOn + ")"));
595	        }
596	    }
597	
598	    private Claim claim(String sheetId, long claimId) {
599	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
600	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
601	        periods.requireOpen(sheetId, claim.getDate());
602	        return claim;
603	    }
604	
605	    /** Log the status a claim has just taken, on the sheet's today, with its due as it is now. */
606	    private void log(String sheetId, String user, Claim claim, Person owner) {
607	        BigDecimal due = owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : claim.getSettledDue())
608	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
609	        claim.logStatus(user, sheets.today(sheetId), due);
610	    }
611	
612	    /** The claim's due now, its late charge frozen in, as settling fixes it. */
613	    private BigDecimal dueNow(String sheetId, Claim claim, Person owner) {
614	        return owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : null)
615	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
616	    }
617	
618	    /**
619	     * Give a claim being opened its number: while the sheet's period numbering from is set and the
620	     * sheet's today is on or after it, the next in the period its date falls in (<period name>-<n>), or
621	     * in the sequence of claims in no period (X-<n>); otherwise the next sheet-wide number. Two users
622	     * taking one at the same moment wait on each other, so no number is given twice or skipped.
623	     */
624	    private void giveNumber(String sheetId, Claim claim) {
625	        if (!numberingOn(sheetId)) {
626	            claim.setNumber(sheets.nextClaimNumber(sheetId));
627	            return;
628	        }
629	        sheetRows.lockById(sheetId);
630	        Period period = periodOf(sheetId, claim.getDate());
631	        String sequence = sequenceOf(sheetId, claim.getDate());
632	        int n = claims.lastInSequence(sheetId, sequence) + 1;
633	        claim.setPeriodNumber(sequence, n, (period == null ? "X" : period.getName()) + "-" + n);
634	    }
635	
636	    /** Whether the sheet's period numbering from is set and the sheet's today is on or after it. */
637	    private boolean numberingOn(String sheetId) {
638	        LocalDate from = sheets.periodNumberingFrom(sheetId);
639	        return from != null && !sheets.today(sheetId).isBefore(from);
640	    }
641	
642	    /** The period whose dates contain the date, or null when none does. */
643	    private Period periodOf(String sheetId, LocalDate date) {
644	        return periods.list(sheetId).stream().filter(p -> p.contains(date)).findFirst().orElse(null);
645	    }
646	
647	    /** The period sequence a claim dated on the date counts in ('P<period id>', or 'X' for no period). */
648	    private String sequenceOf(String sheetId, LocalDate date) {
649	        Period period = periodOf(sheetId, date);
650	        return period == null ? "X" : "P" + period.getId();
651	    }
652	
653	    /**
654	     * Refuse a correction (a negative amount) that does not name the number of a SETTLED claim of the
655	     * same person, and a claim that is not a correction but names one. Returns the date of the claim a
656	     * correction corrects (its rounding goes by it); null for any other claim.
657	     */
658	    private LocalDate requireCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
659	        if (amount.signum() >= 0) {
660	            if (corrects != null) {
661	                throw new ResponseStatusException(HttpStatus.CONFLICT,
662	                        "Only a correction (a negative amount) names a claim it corrects");
663	            }
664	            return null;
665	        }
666	        if (corrects == null) {
667	            throw new ResponseStatusException(HttpStatus.CONFLICT,
668	                    "A negative amount is a correction; name the number of the settled claim it corrects");
669	        }
670	        return claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
671	                .filter(c -> corrects.equals(c.getShownNumber()) && c.getStatus() == ClaimStatus.SETTLED)
672	                .map(Claim::getDate).findFirst()
673	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
674	                        "Claim " + corrects + " is not a settled claim of this person"));
675	    }
676	
677	    /** Refuse a claim dated after its person's retirement date. */
678	    private static void requireNotRetired(Person person, LocalDate date) {
679	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
680	            throw new ResponseStatusException(HttpStatus.CONFLICT,
681	                    person.getName() + " is retired from " + person.getRetiredFrom()
682	                            + "; a claim cannot be dated after that");
683	        }
684	    }
685	}
